+    affect_remove_no_total(&ch, ch.affected);
+  free(GET_TITLE(&ch));
+
+  CuAssertIntEquals(tc, CLASS_WARRIOR, class_after);
+  CuAssertIntEquals(tc, CLASS_UNDEFINED, premade_after);
+}
