+
+  SET_FEAT(&fixture.ch, FEAT_COLD_IMMUNITY, 1);
+  CuAssertIntEquals(tc, base_cold + 100,
+                    compute_damtype_reduction(&fixture.ch, DAM_COLD, NULL, TYPE_UNDEFINED));
+
+  end_innate_fixture(&fixture);
+}
